#!/usr/bin/env python3
"""
Broken profile DP / memoized DFS for counting Hamiltonian paths on grid.
"""

def read_grid(filepath):
    with open(filepath, 'r') as f:
        lines = f.read().strip().split('\n')
    grid = []
    for line in lines:
        row = line.split()
        grid.append(row)
    return grid

def solve(grid):
    cells = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 'X':
                cells.append((r, c))

    n = len(cells)
    if n == 0:
        return 0
    if n == 1:
        return 0  # start != end required

    cell_to_idx = {(r,c): i for i, (r,c) in enumerate(cells)}

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for i, (r, c) in enumerate(cells):
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == 'X':
                adj[i].append(cell_to_idx[(nr, nc)])

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def count_from(current, mask):
        """Count Hamiltonian paths starting from current cell, 
        with mask being the set of ALREADY visited cells (including current)."""
        if mask == (1 << n) - 1:
            return 1  # All cells visited

        total = 0
        for nxt in adj[current]:
            if not (mask & (1 << nxt)):
                total += count_from(nxt, mask | (1 << nxt))
        return total

    # Total directed Hamiltonian paths (counting each direction separately)
    total_directed = 0
    for start in range(n):
        total_directed += count_from(start, 1 << start)

    # Each undirected path is counted twice (once in each direction)
    result = total_directed // 2
    return result

# Test
grid2x2 = [['X','X'],['X','X']]
print(f"2x2 test: {solve(grid2x2)}")

# Actual grid
