print(f"Grid dimensions: {len(grid)}x{len(grid[0])}")

cells = []
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if grid[r][c] == 'X':
            cells.append((r, c))
print(f"Number of X cells: {len(cells)}")

import time
start = time.time()
result = solve(grid)
elapsed = time.time() - start
print(f"Result: {result}, time: {elapsed:.2f}s")
